Voici une fonction C++ qui prend une référence à un std::string contenant du texte au format Markdown et renvoie un std::string contenant du texte au format HTML :

```cpp
#include <iostream>
#include <string>
#include <regex>

std::string convertMarkdownToHtml(const std::string& markdown) {
    // Regular expressions for Markdown syntax
    std::regex bold_regex("([^\\*]+)\\*([^\\*]+)\\*", std::regex::icase);
    std::regex italic_regex("([^_]+)_([^_]+)", std::regex::icase);
    std::regex underline_regex("([^~]+)~([^~]+)", std::regex::icase);
    std::regex strikethrough_regex("([^\\~]+)~~([^\\~]+)", std::regex::icase);
    std::regex link_regex("\\[([^\\]]+)]\\(([^\\)]+)\\)", std::regex::icase);
    std::regex image_regex("!\\[([^\\]]+)]\\(([^\\)]+)\\)", std::regex::icase);
    std::regex heading_regex("^#{1,6}[\\s]+(.+)$", std::regex::icase);
    std::regex blockquote_regex("^> (.+)$", std::regex::icase);
    std::regex code_block_regex("^`{3}(.+?)`{3}$", std::regex::icase);
    std::regex list_item_regex("^\\s*-\\s+(.+)$", std::regex::icase);
    std::regex paragraph_regex("^([\\S\\s]+)$", std::regex::icase);

    std::string html;
    // Convert Markdown to HTML
    std::smatch match;

    // Bold
    while (std::regex_search(markdown, match, bold_regex)) {
        std::string bold_text = match[1] + "<strong>" + match[2] + "</strong>";
        markdown.replace(match.position(), match.length(), bold_text);
    }

    // Italic
    while (std::regex_search(markdown, match, italic_regex)) {
        std::string italic_text = "<em>" + match[1] + "</em>" + match[2];
        markdown.replace(match.position(), match.length(), italic_text);
    }

    // Underline
    while (std::regex_search(markdown, match, underline_regex)) {
        std::string underline_text = "<u>" + match[1] + "</u>" + match[2];
        markdown.replace(match.position(), match.length(), underline_text);
    }

    // Strikethrough
    while (std::regex_search(markdown, match, strikethrough_regex)) {
        std::string strikethrough_text = "<s>" + match[1] + "</s>" + match[2];
        markdown.replace(match.position(), match.length(), strikethrough_text);
    }

    // Links
    while (std::regex_search(markdown, match, link_regex)) {
        std::string link_text = match[1];
        std::string link_url = match[2];
        std::string link_html = "<a href=\"" + link_url + "\">" + link_text + "</a>";
        markdown.replace(match.position(), match.length(), link_html);
    }

    // Images
    while (std::regex_search(markdown, match, image_regex)) {
        std::string image_alt = match[1];
        std::string image_url = match[2];
        std::string image_html = "<img src=\"" + image_url + "\" alt=\"" + image_alt + "\">";
        markdown.replace(match.position(), match.length(), image_html);
    }

    // Headings
    while (std::regex_search(markdown, match, heading_regex)) {
        std::string heading_text = match[1];
        std::string heading_level = std::to_string(match.prefix().length()) + "h";
        std::string heading_html = "<" + heading_level + ">" + heading_text + "</" + heading_level + ">";
        markdown.replace(match.position(), match.length(), heading_html);
    }

    // Blockquote
    while (std::regex_search(markdown, match, blockquote_regex)) {
        std::string blockquote_text = match[1];
        std::string blockquote_html = "<blockquote>" + blockquote_text + "</blockquote>";
        markdown.replace(match.position(), match.length(), blockquote_html);
    }

    // Code blocks
    while (std::regex_search(markdown, match, code_block_regex)) {
        std::string code_text = match[1];
        std::string code_html = "<pre><code>" + code_text + "</code></pre>";
        markdown.replace(match.position(), match.length(), code_html);
    }

    // List items
    while (std::regex_search(markdown, match, list_item_regex)) {
        std::string list_item_text = match[1];
        std::string list_item_html = "<li>" + list_item_text + "</li>";
        markdown.replace(match.position(), match.length(), list_item_html);
    }

    // Paragraphs
    while (std::regex_search(markdown, match, paragraph_regex)) {
        std::string paragraph_text = match[1];
        std::string paragraph_html = "<p>" + paragraph_text + "</p>";
        markdown.replace(match.position(), match.length(), paragraph_html);
    }

    // Return the converted HTML
    return markdown;
}

int main() {
    std::string markdown = "This is a **bold** text. *This is an italic* text. __This is an underline__ text. ~~This is a strikethrough~~ text. [Google](https://www.google.com/) link. ! [Google Logo](https://www.google.com/images/branding/googlelogo/1x/googlelogo_color_272x92dp.png) image. # Heading 1\n## Heading 2\n### Heading 3\n#### Heading 4\n##### Heading 5\n###### Heading 6\n> Blockquote text.\n```\nCode block\nexample\n```";
    std::string html = convertMarkdownToHtml(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

Cette fonction utilise des expressions régulières pour détecter les différentes syntaxes de Markdown (gras, italique, souligné, barré, lien, image, en-tête, citation, bloc de code et liste) et les convertit en HTML respectif. L'exemple de code ci-dessus convertit le texte Markdown fourni en HTML et imprime le résultat dans la console. Il vous faudra cependant adapter cette fonction en fonction de vos besoins, notamment en ajoutant ou en supprimant des cas particuliers selon votre syntaxe Markdown.

