Pour Godot Engine 4.x, le nœud équivalent au KinematicBody est le `RigidBody2D` ou le `RigidBody`. Cependant, le script de contrôleur à la première personne devra être modifié pour fonctionner avec ces nœuds :

```gdscript
extends RigidBody2D

export var speed := 200.0
export var gravity_scale := 0.5
export var jump_speed := -600.0

var velocity := Vector2.ZERO

func _ready():
    # Ajoutez un script de caméra pour la première personne
    var camera = get_node("Camera2D")
    camera.make_current()

func _physics_process(delta):
    var direction := Vector2.ZERO

    if Input.is_action_pressed("move_forward"):
        direction += transform.basis.z
    if Input.is_action_pressed("move_backward"):
        direction -= transform.basis.z
    if Input.is_action_pressed("move_left"):
        direction -= transform.basis.x
    if Input.is_action_pressed("move_right"):
        direction += transform.basis.x

    direction = direction.normalized()

    var gravity_force := Vector2.DOWN * gravity_scale * mass * delta
    velocity += gravity_force

    if is_on_floor():
        if Input.is_action_just_pressed("jump"):
            velocity.y = jump_speed

    var movement := direction * speed
    velocity = move_and_slide(velocity, Vector2.UP)

    # Ajoutez une rotation pour suivre la direction de déplacement
    if direction != Vector2.ZERO:
        var angle := direction.angle_to(Vector2.RIGHT)
        rotation = Quaternion(rotation, Vector2.UP, angle)
```

