```cpp
#include <iostream>
#include <fstream>
#include <string>

using namespace std;

int main() {
    string wordToSearch; // mot à rechercher
    int count = 0; // nombre d'occurrences

    // demander le mot à rechercher
    cout << "Entrer le mot à rechercher: ";
    getline(cin, wordToSearch);

    // ouvrir le fichier pour lecture
    ifstream file("filename.txt");

    if (!file) {
        cout << "Impossible d'ouvrir le fichier." << endl;
        return 1;
    }

    // lire le fichier ligne par ligne
    string line;
    while (getline(file, line)) {
        // séparer la ligne en mots
        size_t pos = 0;
        string token;
        while ((pos = line.find(" ")) != string::npos) {
            token = line.substr(pos, line.find(" ", pos + 1) - pos);
            line.erase(pos, line.find(" ", pos + 1) - pos);

            // vérifier si le mot correspond au mot à rechercher
            if (token == wordToSearch) {
                count++; // incrémenter le compteur
            }
        }

        // vérifier si le dernier mot de la ligne correspond au mot à rechercher
        if (line == wordToSearch) {
            count++; // incrémenter le compteur
        }
    }

    // fermer le fichier
    file.close();

    // afficher le nombre d'occurrences
    cout << "Le mot \"" << wordToSearch << "\" apparaît " << count << " fois dans le fichier." << endl;

    return 0;
}
```

Remplacer `"filename.txt"` par le nom du fichier que vous souhaitez lire, et entrez le mot à rechercher lorsqu'on vous le demande.

